4	/**
5	 * #306: the project skill and CONTRIBUTING gave opposite answers about `version` in
6	 * `package.json`, and a reviewer had to resolve them by reading further than either
7	 * document. They are edited by different hands at different times, and only one of
8	 * them is loaded into every agent run, so the agreement is pinned here.
9	 *
10	 * The agreed procedure (#306): a work pull request never carries the version edit,
11	 * and a release is declared by a person through the **Atomaton Release** workflow,
12	 * whose pull request carries only that edit. Merging it is the release.
13	 */
14	const SKILL = readFileSync("self/atomaton/skills/project/conventions.md", "utf8");
15	const CONTRIBUTING = readFileSync("CONTRIBUTING.md", "utf8");
16	
17	describe("the version procedure is stated the same way in both documents", () => {
18	  test("the skill forbids the edit outright, and names who declares the release", () => {
19	    expect(SKILL).toContain("**Never touch `version` in `package.json`.");
20	    expect(SKILL).toContain("Atomaton Release");
21	    // The old rule made the bump normal whenever "releasing is the task", which is
22	    // every work pull request under the practice it contradicted.
23	    expect(SKILL).not.toContain("unless releasing is the task");
24	  });
25	
26	  test("CONTRIBUTING names the release as a separate declaration, not a bump", () => {
27	    expect(CONTRIBUTING).toContain("dispatch **Atomaton Release**");
28	    expect(CONTRIBUTING).not.toContain("Bump `version` in `package.json` and merge it");
29	  });
30	});

